-- Bounded recovery coordination; migration name generated by Supabase CLI.
BEGIN;
-- Refuse an unexpected execution or tenant-permission owner before any DDL.
DO $precondition$
BEGIN
 IF current_user<>'postgres' OR NOT EXISTS(
  SELECT FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
  WHERE p.oid=to_regprocedure('public.gridex_actor_has_company_permission(uuid,uuid,text)')
   AND r.rolname='postgres' AND p.prosecdef AND md5(p.prosrc)='02c126207b21142e0de62563a287ea1e'
 ) THEN RAISE EXCEPTION 'ediel_recovery_owner_precondition_failed';END IF;
 IF to_regclass('public.ediel_messages') IS NULL OR to_regclass('public.ediel_message_events') IS NULL
  OR to_regclass('public.ediel_outbox') IS NULL OR to_regclass('public.inbound_email_messages') IS NULL OR to_regclass('public.ediel_ack_transaction_results') IS NULL
  THEN RAISE EXCEPTION 'ediel_recovery_source_schema_precondition_failed';END IF;
END $precondition$;
CREATE SCHEMA gridex_ediel_recovery;
REVOKE ALL ON SCHEMA gridex_ediel_recovery FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE gridex_ediel_recovery.cursors(
 kind text NOT NULL CHECK(kind IN('stranded','technical','runtime','held')),environment text NOT NULL CHECK(environment IN('test','production')),
 scope text NOT NULL,company_id uuid,position_at timestamptz NOT NULL,position_id uuid NOT NULL,
 high_at timestamptz NOT NULL,high_id uuid NOT NULL,sweep_complete boolean NOT NULL DEFAULT false,
 PRIMARY KEY(kind,environment,scope),CHECK(scope=coalesce(company_id::text,'*')));
CREATE TABLE gridex_ediel_recovery.lease_cursors(kind text NOT NULL,environment text NOT NULL,scope text NOT NULL,position_at timestamptz NOT NULL DEFAULT '-infinity',position_id uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',reclaim_id uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',PRIMARY KEY(kind,environment,scope));
CREATE TABLE gridex_ediel_recovery.work(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN('stranded','technical','runtime','held')),
 company_id uuid NOT NULL,environment text NOT NULL CHECK(environment IN('test','production')),
 source_id uuid NOT NULL,target_id uuid NOT NULL,payload jsonb NOT NULL DEFAULT '{}',
 state text NOT NULL DEFAULT 'ready' CHECK(state IN('ready','leased','running','uncertain','done','exhausted')),
 attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),max_attempts integer NOT NULL CHECK(max_attempts BETWEEN 1 AND 20),
 next_attempt_at timestamptz NOT NULL DEFAULT clock_timestamp(),claim_token uuid,lease_until timestamptz,lease_grace_seconds integer NOT NULL DEFAULT 600,
 started_at timestamptz,completed_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(kind,company_id,environment,source_id,target_id),CHECK(attempts<=max_attempts),
 FOREIGN KEY(company_id,source_id) REFERENCES public.ediel_messages(company_id,id) ON DELETE CASCADE);
CREATE TABLE gridex_ediel_recovery.source_claims(
 company_id uuid NOT NULL,environment text NOT NULL,source_id uuid NOT NULL,token uuid NOT NULL,
 lease_until timestamptz NOT NULL,PRIMARY KEY(company_id,environment,source_id),
 FOREIGN KEY(company_id,source_id) REFERENCES public.ediel_messages(company_id,id) ON DELETE CASCADE);
ALTER TABLE gridex_ediel_recovery.lease_cursors ENABLE ROW LEVEL SECURITY;
ALTER TABLE gridex_ediel_recovery.lease_cursors FORCE ROW LEVEL SECURITY;
CREATE TABLE gridex_ediel_recovery.terminal_receipts(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),work_id uuid NOT NULL REFERENCES gridex_ediel_recovery.work(id) ON DELETE CASCADE,
 company_id uuid NOT NULL,source_id uuid NOT NULL,token uuid NOT NULL,attempt integer NOT NULL,
 outcome text NOT NULL CHECK(outcome IN('completed','no_effect')),evidence jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(work_id,token,attempt));
CREATE TABLE gridex_ediel_recovery.reconcile_audit(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,work_id uuid NOT NULL REFERENCES gridex_ediel_recovery.work(id) ON DELETE CASCADE,token uuid NOT NULL,
 actor_id uuid NOT NULL,reason text NOT NULL,receipt_id uuid NOT NULL,from_state text NOT NULL,to_state text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE gridex_ediel_recovery.terminal_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE gridex_ediel_recovery.terminal_receipts FORCE ROW LEVEL SECURITY;
ALTER TABLE gridex_ediel_recovery.reconcile_audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE gridex_ediel_recovery.reconcile_audit FORCE ROW LEVEL SECURITY;
ALTER TABLE gridex_ediel_recovery.cursors ENABLE ROW LEVEL SECURITY;
ALTER TABLE gridex_ediel_recovery.cursors FORCE ROW LEVEL SECURITY;
ALTER TABLE gridex_ediel_recovery.work ENABLE ROW LEVEL SECURITY;
ALTER TABLE gridex_ediel_recovery.work FORCE ROW LEVEL SECURITY;
ALTER TABLE gridex_ediel_recovery.source_claims ENABLE ROW LEVEL SECURITY;
ALTER TABLE gridex_ediel_recovery.source_claims FORCE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA gridex_ediel_recovery FROM PUBLIC,anon,authenticated,service_role;
CREATE INDEX ediel_recovery_claim_cursor_idx ON gridex_ediel_recovery.source_claims(environment,source_id);
CREATE INDEX ediel_recovery_ready_idx ON gridex_ediel_recovery.work(kind,environment,created_at,id) WHERE state='ready';
CREATE INDEX ediel_recovery_source_work_idx ON gridex_ediel_recovery.work(company_id,environment,source_id,claim_token,state);
CREATE INDEX ediel_recovery_message_cursor_idx ON public.ediel_messages(created_at,id) WHERE direction='inbound' AND company_id IS NOT NULL;
CREATE INDEX ediel_recovery_held_cursor_idx ON public.ediel_ack_transaction_results(created_at,id) WHERE disposition='internal_review' AND final_response_type IS NULL AND finalized_at IS NULL AND response_message_id IS NULL;
CREATE INDEX ediel_recovery_held_source_idx ON public.ediel_ack_transaction_results(company_id,environment,source_message_id,updated_at) WHERE disposition='internal_review' AND final_response_type IS NULL AND finalized_at IS NULL AND response_message_id IS NULL;
CREATE INDEX ediel_recovery_technical_cursor_idx ON public.ediel_message_events(created_at,id) WHERE event_type='manual_note' AND payload->>'blockedBy'='canonical_inbound_ack_guard' AND payload->>'ackFamily'='CONTRL';
CREATE INDEX ediel_recovery_runtime_cursor_idx ON public.ediel_message_events(created_at,id) WHERE event_type IN('contrl_sent','aperak_sent','utilts_err_sent') AND message IN('CONTRL hanterad via canonical kernel.','APERAK hanterad via canonical kernel.','UTILTS_ERR hanterad via canonical kernel.');
CREATE INDEX ediel_recovery_attempts_idx ON public.ediel_message_events(ediel_message_id,(payload->>'resume'),company_id) WHERE event_type='manual_note' AND payload->>'kind'='attempt' AND payload->>'resume' IN('stranded_inbound_business_processing','missed_technical_ack','unqueued_utilts_runtime_reply','held_utilts_resume');

CREATE FUNCTION gridex_ediel_recovery.service_v1() RETURNS void LANGUAGE plpgsql SET search_path TO pg_catalog AS $$
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN
  RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
END $$;

-- Returns only a locally eligible target, never guide/actor/write authority.
CREATE FUNCTION gridex_ediel_recovery.eligible_v1(w gridex_ediel_recovery.work,grace_seconds integer) RETURNS jsonb
 LANGUAGE plpgsql STABLE SET search_path TO pg_catalog AS $$
DECLARE s public.ediel_messages%rowtype;a public.ediel_messages%rowtype;mail public.inbound_email_messages%rowtype;
BEGIN
 SELECT * INTO s FROM public.ediel_messages WHERE id=w.source_id AND company_id=w.company_id AND environment=w.environment;
 IF NOT FOUND OR s.direction<>'inbound' OR s.message_standard<>'edifact' OR s.status='cancelled' THEN RETURN NULL;END IF;
 IF s.updated_at IS NULL OR s.updated_at>statement_timestamp()-make_interval(secs=>grace_seconds) THEN RETURN NULL;END IF;
 IF w.kind='held' THEN
  -- A source callback covers all current held transactions. One old row cannot
  -- authorize it when another same-scope held row became fresh after selection.
  IF s.message_family<>'UTILTS' OR NOT EXISTS(SELECT FROM public.ediel_ack_transaction_results h WHERE h.company_id=w.company_id AND h.environment=w.environment AND h.source_message_id=w.source_id AND h.updated_at<statement_timestamp()-make_interval(secs=>grace_seconds) AND h.disposition='internal_review' AND h.final_response_type IS NULL AND h.finalized_at IS NULL AND h.response_message_id IS NULL) OR EXISTS(SELECT FROM public.ediel_ack_transaction_results h WHERE h.company_id=w.company_id AND h.environment=w.environment AND h.source_message_id=w.source_id AND h.updated_at>=statement_timestamp()-make_interval(secs=>grace_seconds) AND h.disposition='internal_review' AND h.final_response_type IS NULL AND h.finalized_at IS NULL AND h.response_message_id IS NULL) THEN RETURN NULL;END IF;
  RETURN jsonb_build_object('sourceMessageId',s.id,'companyId',s.company_id);
 ELSIF w.kind='stranded' THEN
  IF s.status IS DISTINCT FROM 'received' OR s.processing_status IS DISTINCT FROM 'received'
   OR s.tenant_resolution_status IS DISTINCT FROM 'tenant_resolved' OR s.updated_at IS NULL
   OR s.updated_at>statement_timestamp()-make_interval(secs=>grace_seconds) THEN RETURN NULL;END IF;
  SELECT * INTO mail FROM public.inbound_email_messages WHERE id=s.inbound_email_message_id AND company_id=s.company_id;
  IF NOT FOUND OR mail.processing_status IS DISTINCT FROM 'processed' OR mail.match_status='dsn_transport_review'
   OR mail.environment IS DISTINCT FROM w.environment THEN RETURN NULL;END IF;
  RETURN jsonb_build_object('id',s.id,'companyId',s.company_id);
 ELSIF w.kind='technical' THEN
  IF s.message_family='CONTRL' OR (coalesce(s.status='received',false) AND coalesce(s.processing_status='received',false)) THEN RETURN NULL;END IF;
  IF w.target_id=s.id THEN
   IF EXISTS(SELECT FROM public.ediel_messages x WHERE x.related_message_id=s.id AND x.direction='outbound' AND x.message_family='CONTRL') THEN RETURN NULL;END IF;
   RETURN jsonb_build_object('kind','missing','messageId',s.id,'sourceMessageId',s.id,'companyId',s.company_id);
  END IF;
 ELSE
  IF s.message_family<>'UTILTS' OR (w.environment='production' AND (s.sender_ediel_id='91100' OR s.receiver_ediel_id='91100')) THEN RETURN NULL;END IF;
 END IF;
 SELECT * INTO a FROM public.ediel_messages WHERE id=w.target_id AND company_id=s.company_id AND environment=s.environment
  AND related_message_id=s.id AND direction='outbound' AND status='draft';
 IF NOT FOUND OR EXISTS(SELECT FROM public.ediel_outbox o WHERE o.ediel_message_id=a.id) THEN RETURN NULL;END IF;
 IF w.kind='technical' THEN
  IF a.message_family<>'CONTRL' THEN RETURN NULL;END IF;
  RETURN jsonb_build_object('kind','unqueued','messageId',a.id,'sourceMessageId',s.id,'companyId',s.company_id);
 END IF;
 IF a.message_family NOT IN('CONTRL','APERAK','UTILTS_ERR') OR a.message_family IS DISTINCT FROM w.payload->>'ackFamily'
  OR (a.message_family='CONTRL' AND EXISTS(SELECT FROM public.ediel_message_events e WHERE e.ediel_message_id=s.id
    AND e.event_type='manual_note' AND e.payload->>'blockedBy'='canonical_inbound_ack_guard' AND e.payload->>'ackFamily'='CONTRL')) THEN RETURN NULL;END IF;
 IF NOT ((w.payload->>'provenance'='queue_failed' AND w.payload->>'replyDispatch'='operational_outbox')
  OR(w.payload->>'provenance'='pre_f112' AND w.environment='production' AND w.payload->>'replyDispatch' IS NULL)) THEN RETURN NULL;END IF;
 RETURN w.payload||jsonb_build_object('ackMessageId',a.id,'sourceMessageId',s.id,'companyId',s.company_id,'ackFamily',a.message_family);
END $$;

CREATE FUNCTION gridex_ediel_recovery.put_v1(p_kind text,p_environment text,p_source_id uuid,p_target_id uuid,p_payload jsonb,p_max_attempts integer) RETURNS void
 LANGUAGE plpgsql SET search_path TO pg_catalog AS $$
DECLARE s public.ediel_messages%rowtype;marker text;n integer;v_work gridex_ediel_recovery.work%rowtype;
BEGIN
 SELECT * INTO s FROM public.ediel_messages m WHERE m.id=p_source_id AND m.direction='inbound' AND m.company_id IS NOT NULL AND m.environment=p_environment;
 IF NOT FOUND OR EXISTS(SELECT FROM gridex_ediel_recovery.work w WHERE w.kind=p_kind AND w.environment=p_environment AND w.company_id=s.company_id AND w.source_id=s.id AND w.target_id=p_target_id) THEN RETURN;END IF;
 v_work.kind:=p_kind;v_work.company_id:=s.company_id;v_work.environment:=p_environment;v_work.source_id:=s.id;v_work.target_id:=p_target_id;v_work.payload:=p_payload;
 IF gridex_ediel_recovery.eligible_v1(v_work,120) IS NULL THEN RETURN;END IF;
 marker:=CASE p_kind WHEN 'stranded' THEN 'stranded_inbound_business_processing' WHEN 'technical' THEN 'missed_technical_ack' WHEN 'held' THEN 'held_utilts_resume' ELSE 'unqueued_utilts_runtime_reply' END;
 -- Disjoint tenant-index seeks; neither branch scans a foreign-tenant prefix.
 SELECT count(*) INTO n FROM(
  (SELECT 1 FROM public.ediel_message_events e WHERE e.company_id=s.company_id AND e.ediel_message_id=p_target_id AND e.event_type='manual_note' AND e.payload->>'resume'=marker AND e.payload->>'kind'='attempt' AND e.payload->>'resume' IN('stranded_inbound_business_processing','missed_technical_ack','unqueued_utilts_runtime_reply','held_utilts_resume') LIMIT p_max_attempts)
  UNION ALL
  (SELECT 1 FROM public.ediel_message_events e WHERE e.company_id IS NULL AND e.ediel_message_id=p_target_id AND e.event_type='manual_note' AND e.payload->>'resume'=marker AND e.payload->>'kind'='attempt' AND e.payload->>'resume' IN('stranded_inbound_business_processing','missed_technical_ack','unqueued_utilts_runtime_reply','held_utilts_resume') LIMIT p_max_attempts)
  LIMIT p_max_attempts
 ) attempts;
 INSERT INTO gridex_ediel_recovery.work(kind,company_id,environment,source_id,target_id,payload,attempts,max_attempts,state)
 VALUES(p_kind,s.company_id,p_environment,s.id,p_target_id,p_payload,n,p_max_attempts,CASE WHEN n>=p_max_attempts THEN 'exhausted' ELSE 'ready' END)
 ON CONFLICT DO NOTHING;
END $$;

CREATE FUNCTION public.ediel_recovery_discover_v1(p_kind text,p_environment text,p_company uuid DEFAULT NULL,p_page integer DEFAULT 200,p_grace_seconds integer DEFAULT 600,p_lookback_hours integer DEFAULT 72,p_max_attempts integer DEFAULT 3) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog SET "TimeZone" TO UTC SET lock_timeout TO '100ms' AS $$
DECLARE c gridex_ediel_recovery.cursors%rowtype;r record;s public.ediel_messages%rowtype;a public.ediel_messages%rowtype;
 v_scope text:=coalesce(p_company::text,'*');n integer:=0;family text;payload jsonb;provenance text;v_page jsonb;
BEGIN
 PERFORM gridex_ediel_recovery.service_v1();
 IF p_kind IS NULL OR p_environment IS NULL OR p_kind NOT IN('stranded','technical','runtime','held') OR p_environment NOT IN('test','production') OR p_page IS NULL OR p_grace_seconds IS NULL OR p_lookback_hours IS NULL OR p_max_attempts IS NULL OR p_page NOT BETWEEN 1 AND 200
  OR p_grace_seconds NOT BETWEEN 120 AND 86400 OR p_lookback_hours NOT BETWEEN 1 AND (CASE WHEN p_kind='held' THEN 8760 WHEN p_kind='stranded' THEN 2160 ELSE 720 END)
  OR p_max_attempts NOT BETWEEN 1 AND (CASE WHEN p_kind='held' THEN 20 ELSE 10 END) THEN RAISE EXCEPTION 'ediel_recovery_input_invalid';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('ediel-recovery-cursor|'||p_kind||'|'||p_environment||'|'||v_scope,0)) THEN RETURN jsonb_build_object('busy',true,'scanned',0);END IF;
 INSERT INTO gridex_ediel_recovery.cursors(kind,environment,scope,company_id,position_at,position_id,high_at,high_id)
 VALUES(p_kind,p_environment,v_scope,p_company,statement_timestamp()-make_interval(hours=>p_lookback_hours),'00000000-0000-0000-0000-000000000000',statement_timestamp()-make_interval(secs=>p_grace_seconds),'ffffffff-ffff-ffff-ffff-ffffffffffff') ON CONFLICT DO NOTHING;
 SELECT * INTO c FROM gridex_ediel_recovery.cursors x WHERE x.kind=p_kind AND x.environment=p_environment AND x.scope=v_scope FOR UPDATE;
 IF c.sweep_complete THEN
  c.position_at:=statement_timestamp()-make_interval(hours=>p_lookback_hours);c.position_id:='00000000-0000-0000-0000-000000000000';c.high_at:=statement_timestamp()-make_interval(secs=>p_grace_seconds);c.high_id:='ffffffff-ffff-ffff-ffff-ffffffffffff';
 END IF;
 IF p_kind='held' THEN
  -- The hold ledger owns the lookback window. A retained source may predate
  -- that window by months and still have a newly held transaction.
  -- Advance a raw indexed page before tenant/lane/grace checks and dedupe work
  -- by source below, so duplicate/foreign ledger rows cannot pin discovery.
  SELECT coalesce(jsonb_agg(to_jsonb(page)),'[]') INTO v_page FROM(SELECT x.id,x.created_at,x.company_id,x.source_message_id ediel_message_id,x.environment source_environment,'held'::text event_type,NULL::text message,'{}'::jsonb payload FROM public.ediel_ack_transaction_results x WHERE x.disposition='internal_review' AND x.final_response_type IS NULL AND x.finalized_at IS NULL AND x.response_message_id IS NULL AND (x.created_at,x.id)>(c.position_at,c.position_id) AND (x.created_at,x.id)<=(c.high_at,c.high_id) ORDER BY x.created_at,x.id LIMIT p_page)page;
 ELSIF p_kind='stranded' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page)),'[]') INTO v_page FROM(SELECT x.id,x.created_at,x.company_id,x.id ediel_message_id,'source'::text event_type,NULL::text message,'{}'::jsonb payload FROM public.ediel_messages x WHERE x.direction='inbound' AND x.company_id IS NOT NULL AND (x.created_at,x.id)>(c.position_at,c.position_id) AND (x.created_at,x.id)<=(c.high_at,c.high_id) ORDER BY x.created_at,x.id LIMIT p_page)page;
 ELSIF p_kind='technical' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page)),'[]') INTO v_page FROM(SELECT x.id,x.created_at,x.company_id,x.ediel_message_id,x.event_type,x.message,x.payload FROM public.ediel_message_events x WHERE x.event_type='manual_note' AND x.payload->>'blockedBy'='canonical_inbound_ack_guard' AND x.payload->>'ackFamily'='CONTRL' AND (x.created_at,x.id)>(c.position_at,c.position_id) AND (x.created_at,x.id)<=(c.high_at,c.high_id) ORDER BY x.created_at,x.id LIMIT p_page)page;
 ELSE
  SELECT coalesce(jsonb_agg(to_jsonb(page)),'[]') INTO v_page FROM(SELECT x.id,x.created_at,x.company_id,x.ediel_message_id,x.event_type,x.message,x.payload FROM public.ediel_message_events x WHERE x.event_type IN('contrl_sent','aperak_sent','utilts_err_sent') AND x.message IN('CONTRL hanterad via canonical kernel.','APERAK hanterad via canonical kernel.','UTILTS_ERR hanterad via canonical kernel.') AND (x.created_at,x.id)>(c.position_at,c.position_id) AND (x.created_at,x.id)<=(c.high_at,c.high_id) ORDER BY x.created_at,x.id LIMIT p_page)page;
 END IF;
 FOR r IN SELECT * FROM jsonb_to_recordset(v_page) AS page(id uuid,created_at timestamptz,company_id uuid,ediel_message_id uuid,event_type text,message text,payload jsonb,source_environment text)
 LOOP
  n:=n+1;c.position_at:=r.created_at;c.position_id:=r.id;
  SELECT * INTO s FROM public.ediel_messages m WHERE m.id=r.ediel_message_id AND m.environment=p_environment AND m.company_id IS NOT NULL
   AND m.direction='inbound' AND m.message_standard='edifact' AND (p_company IS NULL OR m.company_id=p_company)
   AND (r.company_id IS NULL OR r.company_id=m.company_id);
  IF NOT FOUND THEN CONTINUE;END IF;
  IF p_kind='held' THEN
   IF r.source_environment IS DISTINCT FROM p_environment OR NOT EXISTS(SELECT FROM public.ediel_ack_transaction_results h WHERE h.id=r.id AND h.company_id=s.company_id AND h.environment=p_environment AND h.source_message_id=s.id AND h.created_at=r.created_at AND h.updated_at<statement_timestamp()-make_interval(secs=>p_grace_seconds) AND h.disposition='internal_review' AND h.final_response_type IS NULL AND h.finalized_at IS NULL AND h.response_message_id IS NULL) THEN CONTINUE;END IF;
   PERFORM gridex_ediel_recovery.put_v1(p_kind,p_environment,s.id,s.id,'{}',p_max_attempts);
  ELSIF p_kind='stranded' THEN
   IF s.status='received' AND s.processing_status='received' AND s.tenant_resolution_status='tenant_resolved' THEN
    PERFORM gridex_ediel_recovery.put_v1(p_kind,p_environment,s.id,s.id,'{}',p_max_attempts);END IF;
  ELSIF p_kind='technical' THEN
   IF NOT EXISTS(SELECT FROM public.ediel_messages x WHERE x.related_message_id=s.id AND x.direction='outbound' AND x.message_family='CONTRL') THEN
    PERFORM gridex_ediel_recovery.put_v1(p_kind,p_environment,s.id,s.id,'{}',p_max_attempts);
   ELSE
    FOR a IN SELECT * FROM public.ediel_messages x WHERE x.related_message_id=s.id AND x.company_id=s.company_id AND x.environment=s.environment AND x.direction='outbound' AND x.message_family='CONTRL' AND x.status='draft'
     AND NOT EXISTS(SELECT FROM public.ediel_outbox o WHERE o.ediel_message_id=x.id) ORDER BY x.id LIMIT 2 LOOP
     PERFORM gridex_ediel_recovery.put_v1(p_kind,p_environment,s.id,a.id,'{}',p_max_attempts);
    END LOOP;
   END IF;
  ELSE
   family:=CASE r.message WHEN 'CONTRL hanterad via canonical kernel.' THEN 'CONTRL' WHEN 'APERAK hanterad via canonical kernel.' THEN 'APERAK' WHEN 'UTILTS_ERR hanterad via canonical kernel.' THEN 'UTILTS_ERR' END;
   provenance:=CASE WHEN r.payload->>'replyDispatch'='operational_outbox' AND r.payload->>'outboxQueued'='false' THEN 'queue_failed' WHEN p_environment='production' AND r.payload->>'replyDispatch' IS NULL THEN 'pre_f112' END;
   IF provenance IS NULL OR coalesce(r.payload->>'ackMessageId','')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN CONTINUE;END IF;
   payload:=jsonb_build_object('ackFamily',family,'provenance',provenance,'replyDispatch',r.payload->>'replyDispatch',
    'outcome',CASE WHEN r.payload->>'outcome' IN('positive','negative') THEN r.payload->>'outcome' END,
    'ackScope',CASE WHEN jsonb_typeof(r.payload->'ackScope')='string' THEN nullif(btrim(r.payload->>'ackScope'),'') END,
    'relatedTransactionReference',CASE WHEN jsonb_typeof(r.payload->'relatedTransactionReference')='string' THEN nullif(btrim(r.payload->>'relatedTransactionReference'),'') END);
   PERFORM gridex_ediel_recovery.put_v1(p_kind,p_environment,s.id,(r.payload->>'ackMessageId')::uuid,payload,p_max_attempts);
  END IF;
 END LOOP;
 UPDATE gridex_ediel_recovery.cursors x SET position_at=c.position_at,position_id=c.position_id,high_at=c.high_at,high_id=c.high_id,sweep_complete=(n<p_page)
 WHERE x.kind=p_kind AND x.environment=p_environment AND x.scope=v_scope;
 RETURN jsonb_build_object('scanned',n,'complete',n<p_page,'highWatermark',c.high_at);
END $$;

CREATE FUNCTION public.ediel_recovery_lease_v1(p_kind text,p_environment text,p_company uuid DEFAULT NULL,p_exclude uuid[] DEFAULT '{}',p_source_limit integer DEFAULT 10,p_target_limit integer DEFAULT 50,p_grace_seconds integer DEFAULT 600) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog SET "TimeZone" TO UTC SET lock_timeout TO '100ms' AS $$
DECLARE candidate record;w gridex_ediel_recovery.work%rowtype;claim gridex_ediel_recovery.source_claims%rowtype;target jsonb;answer jsonb:='[]';sources uuid[]:='{}';v_token uuid:=gen_random_uuid();until timestamptz:=statement_timestamp()+interval '60 seconds';v_cursor gridex_ediel_recovery.lease_cursors%rowtype;v_scope text:=coalesce(p_company::text,'*');v_scanned integer:=0;v_reclaimed integer:=0;
BEGIN
 PERFORM gridex_ediel_recovery.service_v1();
 IF p_kind IS NULL OR p_environment IS NULL OR p_kind NOT IN('stranded','technical','runtime','held') OR p_environment NOT IN('test','production') OR p_source_limit IS NULL OR p_target_limit IS NULL OR p_grace_seconds IS NULL OR p_source_limit NOT BETWEEN 1 AND 50
  OR p_target_limit NOT BETWEEN 1 AND 50 OR p_grace_seconds NOT BETWEEN 120 AND 86400 OR cardinality(p_exclude)>500 THEN RAISE EXCEPTION 'ediel_recovery_input_invalid';END IF;
 INSERT INTO gridex_ediel_recovery.lease_cursors(kind,environment,scope) VALUES(p_kind,p_environment,v_scope) ON CONFLICT DO NOTHING;
 SELECT * INTO v_cursor FROM gridex_ediel_recovery.lease_cursors x WHERE x.kind=p_kind AND x.environment=p_environment AND x.scope=v_scope FOR UPDATE;
 -- Reclaim only leases with no started/uncertain effect. Source lock and token
 -- tests below fence a delayed START; a RUNNING timeout is never stolen.
 -- Select a bounded raw page BEFORE row locks. Applying LIMIT after SKIP
 -- LOCKED could walk an arbitrarily large locked prefix to find fifty rows.
 FOR candidate IN SELECT c.company_id,c.environment,c.source_id FROM gridex_ediel_recovery.source_claims c WHERE c.environment=p_environment
  AND c.source_id>v_cursor.reclaim_id ORDER BY c.source_id LIMIT 50 LOOP
  v_reclaimed:=v_reclaimed+1;v_cursor.reclaim_id:=candidate.source_id;
  SELECT * INTO claim FROM gridex_ediel_recovery.source_claims c WHERE c.company_id=candidate.company_id AND c.environment=candidate.environment AND c.source_id=candidate.source_id FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN CONTINUE;END IF;
  IF claim.lease_until>=statement_timestamp() OR(p_company IS NOT NULL AND claim.company_id<>p_company)
   OR EXISTS(SELECT FROM gridex_ediel_recovery.work z WHERE z.company_id=claim.company_id AND z.environment=claim.environment AND z.source_id=claim.source_id AND z.claim_token=claim.token AND z.state IN('running','uncertain')) THEN CONTINUE;END IF;
  UPDATE gridex_ediel_recovery.work SET state='ready',claim_token=NULL,lease_until=NULL WHERE id IN(SELECT x.id FROM gridex_ediel_recovery.work x WHERE x.company_id=claim.company_id AND x.environment=claim.environment AND x.source_id=claim.source_id AND x.claim_token=claim.token AND x.state='leased' FOR UPDATE SKIP LOCKED);
  IF EXISTS(SELECT FROM gridex_ediel_recovery.work x WHERE x.company_id=claim.company_id AND x.environment=claim.environment AND x.source_id=claim.source_id AND x.claim_token=claim.token AND x.state='leased') THEN CONTINUE;END IF;
  DELETE FROM gridex_ediel_recovery.source_claims c WHERE c.company_id=claim.company_id AND c.environment=claim.environment AND c.source_id=claim.source_id AND c.token=claim.token;
 END LOOP;
 FOR candidate IN SELECT x.id,x.created_at FROM gridex_ediel_recovery.work x WHERE x.kind=p_kind AND x.environment=p_environment
  AND x.state='ready' AND (x.created_at,x.id)>(v_cursor.position_at,v_cursor.position_id)
  ORDER BY x.created_at,x.id LIMIT 200 LOOP
  v_scanned:=v_scanned+1;v_cursor.position_at:=candidate.created_at;v_cursor.position_id:=candidate.id;
  SELECT * INTO w FROM gridex_ediel_recovery.work x WHERE x.id=candidate.id AND x.state='ready' FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN CONTINUE;END IF;
  IF (p_company IS NOT NULL AND w.company_id<>p_company) OR w.attempts>=w.max_attempts OR w.next_attempt_at>statement_timestamp() OR w.source_id=ANY(coalesce(p_exclude,'{}'))
   OR EXISTS(SELECT FROM gridex_ediel_recovery.source_claims x WHERE x.company_id=w.company_id AND x.environment=w.environment AND x.source_id=w.source_id AND x.token<>v_token)
   THEN CONTINUE;END IF;
  target:=gridex_ediel_recovery.eligible_v1(w,p_grace_seconds);IF target IS NULL THEN CONTINUE;END IF;
  IF NOT(w.source_id=ANY(sources)) AND cardinality(sources)>=p_source_limit THEN CONTINUE;END IF;
  IF NOT pg_try_advisory_xact_lock(hashtextextended('ediel-recovery-source|'||w.company_id::text||'|'||w.environment||'|'||w.source_id::text,0)) THEN CONTINUE;END IF;
  IF NOT(w.source_id=ANY(sources)) THEN
   INSERT INTO gridex_ediel_recovery.source_claims(company_id,environment,source_id,token,lease_until) VALUES(w.company_id,w.environment,w.source_id,v_token,until) ON CONFLICT DO NOTHING;
   IF NOT FOUND THEN CONTINUE;END IF;sources:=array_append(sources,w.source_id);
  END IF;
  target:=gridex_ediel_recovery.eligible_v1(w,p_grace_seconds);IF target IS NULL THEN CONTINUE;END IF;
  UPDATE gridex_ediel_recovery.work SET state='leased',claim_token=v_token,lease_until=until,lease_grace_seconds=p_grace_seconds WHERE id=w.id;
  answer:=answer||jsonb_build_array(target||jsonb_build_object('recovery',jsonb_build_object('workId',w.id,'token',v_token,'leaseUntil',until),'attempt',w.attempts+1,'maxAttempts',w.max_attempts));
  IF jsonb_array_length(answer)>=p_target_limit THEN EXIT;END IF;
 END LOOP;
 IF v_reclaimed=0 THEN v_cursor.reclaim_id:='00000000-0000-0000-0000-000000000000';END IF;
 IF v_scanned=0 THEN v_cursor.position_at:='-infinity';v_cursor.position_id:='00000000-0000-0000-0000-000000000000';END IF;
 UPDATE gridex_ediel_recovery.lease_cursors x SET position_at=v_cursor.position_at,position_id=v_cursor.position_id,reclaim_id=v_cursor.reclaim_id WHERE x.kind=p_kind AND x.environment=p_environment AND x.scope=v_scope;
 RETURN jsonb_build_object('scanned',v_scanned,'claimed',answer,'claimedSources',cardinality(sources),'candidates',jsonb_array_length(answer));
END $$;


-- This terminal receipt is emitted by the trusted execution owner only after its
-- awaited callback resolved with an explicitly recognized terminal outcome.
-- Any thrown/network/unknown outcome has no receipt and remains uncertain.
CREATE FUNCTION public.ediel_recovery_record_terminal_v1(p_work uuid,p_token uuid,p_company uuid,p_expected_state text,p_outcome text) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog SET lock_timeout TO '100ms' AS $$
DECLARE w gridex_ediel_recovery.work%rowtype;s public.ediel_messages%rowtype;v_evidence jsonb;v_receipt uuid;v_proven boolean:=false;
BEGIN
 PERFORM gridex_ediel_recovery.service_v1();
 IF p_work IS NULL OR p_token IS NULL OR p_company IS NULL OR p_expected_state IS NULL OR p_outcome IS NULL
  OR p_expected_state NOT IN('running','uncertain') OR p_outcome NOT IN('completed','no_effect') THEN RAISE EXCEPTION 'ediel_recovery_terminal_input_invalid';END IF;
 SELECT * INTO w FROM gridex_ediel_recovery.work WHERE id=p_work AND company_id=p_company FOR UPDATE;
 IF NOT FOUND OR w.state<>p_expected_state OR w.claim_token IS DISTINCT FROM p_token OR w.attempts<1
  OR NOT EXISTS(SELECT FROM gridex_ediel_recovery.source_claims c WHERE c.company_id=w.company_id AND c.environment=w.environment AND c.source_id=w.source_id AND c.token=p_token)
  THEN RAISE EXCEPTION 'ediel_recovery_terminal_stale';END IF;
 SELECT * INTO s FROM public.ediel_messages WHERE id=w.source_id AND company_id=w.company_id AND environment=w.environment;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_recovery_terminal_source_missing';END IF;
 IF p_outcome='completed' THEN
  IF w.kind='held' THEN
   -- Correlated terminal event is emitted by the retained-original owner only
   -- after the actual runtime and its post-runtime ledger read have settled.
   v_proven:=EXISTS(SELECT FROM public.ediel_message_events e WHERE e.company_id=w.company_id AND e.ediel_message_id=w.source_id AND e.event_type='manual_note' AND e.created_at>=w.started_at AND e.payload->>'resume'='held_utilts_resume' AND e.payload->>'kind'='result' AND e.payload->>'recoveryToken'=p_token::text AND e.payload->>'attempt'=w.attempts::text AND e.payload->>'outcome' IN('processed','still_held'));
  ELSIF w.kind='stranded' THEN v_proven:=s.status IS DISTINCT FROM 'received' OR s.processing_status IS DISTINCT FROM 'received';
  ELSIF w.kind='technical' AND w.target_id=w.source_id THEN
   v_proven:=EXISTS(SELECT FROM public.ediel_messages a WHERE a.related_message_id=w.source_id AND a.company_id=w.company_id AND a.environment=w.environment AND a.direction='outbound' AND a.message_family='CONTRL' AND a.status<>'cancelled');
  ELSE
   v_proven:=EXISTS(SELECT FROM public.ediel_outbox o WHERE o.ediel_message_id=w.target_id AND o.company_id=w.company_id AND o.environment=w.environment AND o.source_message_id=w.source_id);
  END IF;
 ELSE
  -- An explicitly readonly not-applicable result additionally needs current
  -- ineligibility. It is never inferred from a caught or timed-out write.
  v_proven:=gridex_ediel_recovery.eligible_v1(w,w.lease_grace_seconds) IS NULL;
 END IF;
 IF NOT coalesce(v_proven,false) THEN RAISE EXCEPTION 'ediel_recovery_terminal_evidence_missing';END IF;
 v_evidence:=jsonb_build_object('kind',w.kind,'environment',w.environment,'sourceId',w.source_id,'targetId',w.target_id,'sourceStatus',s.status,'sourceProcessingStatus',s.processing_status);
 INSERT INTO gridex_ediel_recovery.terminal_receipts(work_id,company_id,source_id,token,attempt,outcome,evidence)
 VALUES(w.id,w.company_id,w.source_id,p_token,w.attempts,p_outcome,v_evidence) ON CONFLICT DO NOTHING;
 SELECT id INTO v_receipt FROM gridex_ediel_recovery.terminal_receipts WHERE work_id=w.id AND token=p_token AND attempt=w.attempts AND outcome=p_outcome;
 IF v_receipt IS NULL THEN RAISE EXCEPTION 'ediel_recovery_terminal_receipt_conflict';END IF;
 RETURN jsonb_build_object('receiptId',v_receipt);
END $$;
CREATE FUNCTION public.ediel_recovery_transition_v1(p_work uuid,p_token uuid,p_operation text,p_error text DEFAULT NULL) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog SET "TimeZone" TO UTC SET lock_timeout TO '100ms' AS $$
DECLARE w gridex_ediel_recovery.work%rowtype;c gridex_ediel_recovery.source_claims%rowtype;resolved boolean:=false;s public.ediel_messages%rowtype;
BEGIN
 PERFORM gridex_ediel_recovery.service_v1();
 IF p_work IS NULL OR p_token IS NULL OR p_operation IS NULL OR p_operation NOT IN('start','finish','uncertain','release') OR octet_length(coalesce(p_error,''))>2000 THEN RAISE EXCEPTION 'ediel_recovery_input_invalid';END IF;
 SELECT * INTO w FROM gridex_ediel_recovery.work WHERE id=p_work FOR UPDATE;
 IF NOT FOUND OR w.claim_token IS DISTINCT FROM p_token THEN RAISE EXCEPTION 'ediel_recovery_stale_token';END IF;
 SELECT * INTO c FROM gridex_ediel_recovery.source_claims WHERE company_id=w.company_id AND environment=w.environment AND source_id=w.source_id FOR UPDATE;
 IF NOT FOUND OR c.token IS DISTINCT FROM p_token THEN RAISE EXCEPTION 'ediel_recovery_stale_token';END IF;
 IF p_operation='start' THEN
  IF w.state<>'leased' OR w.lease_until<=statement_timestamp() OR w.attempts>=w.max_attempts OR gridex_ediel_recovery.eligible_v1(w,w.lease_grace_seconds) IS NULL THEN RAISE EXCEPTION 'ediel_recovery_start_refused';END IF;
  UPDATE gridex_ediel_recovery.work SET state='running',attempts=attempts+1,started_at=clock_timestamp() WHERE id=w.id RETURNING * INTO w;
  RETURN jsonb_build_object('attempt',w.attempts,'maxAttempts',w.max_attempts);
 ELSIF p_operation='release' THEN
  IF w.state<>'leased' THEN RAISE EXCEPTION 'ediel_recovery_started_release_refused';END IF;
  UPDATE gridex_ediel_recovery.work SET state='ready',claim_token=NULL,lease_until=NULL WHERE id=w.id RETURNING * INTO w;
 ELSE
  IF w.state NOT IN('running','uncertain') THEN RAISE EXCEPTION 'ediel_recovery_not_running';END IF;
  IF p_operation='uncertain' THEN
   UPDATE gridex_ediel_recovery.work SET state='uncertain',last_error=p_error WHERE id=w.id;
   RETURN jsonb_build_object('state','uncertain');
  END IF;
  IF NOT EXISTS(SELECT FROM gridex_ediel_recovery.terminal_receipts r WHERE r.work_id=w.id AND r.company_id=w.company_id AND r.source_id=w.source_id AND r.token=p_token AND r.attempt=w.attempts) THEN RAISE EXCEPTION 'ediel_recovery_terminal_receipt_required';END IF;
  SELECT * INTO s FROM public.ediel_messages WHERE id=w.source_id AND company_id=w.company_id AND environment=w.environment;
  IF w.kind='held' THEN resolved:=gridex_ediel_recovery.eligible_v1(w,0) IS NULL;
  ELSIF w.kind='stranded' THEN resolved:=NOT FOUND OR s.status IS DISTINCT FROM 'received' OR s.processing_status IS DISTINCT FROM 'received';
  ELSIF w.target_id=w.source_id THEN resolved:=EXISTS(SELECT FROM public.ediel_messages a WHERE a.related_message_id=w.source_id AND a.company_id=w.company_id AND a.environment=w.environment AND a.direction='outbound' AND a.message_family='CONTRL');
  ELSE resolved:=EXISTS(SELECT FROM public.ediel_outbox o WHERE o.ediel_message_id=w.target_id)
   OR NOT EXISTS(SELECT FROM public.ediel_messages a WHERE a.id=w.target_id AND a.company_id=w.company_id AND a.environment=w.environment AND a.direction='outbound' AND a.status='draft');END IF;
  UPDATE gridex_ediel_recovery.work SET state=CASE WHEN resolved THEN 'done' WHEN attempts>=max_attempts THEN 'exhausted' ELSE 'ready' END,
   completed_at=clock_timestamp(),last_error=p_error,next_attempt_at=clock_timestamp()+interval '2 minutes',claim_token=NULL,lease_until=NULL WHERE id=w.id RETURNING * INTO w;
 END IF;
 IF NOT EXISTS(SELECT FROM gridex_ediel_recovery.work x WHERE x.company_id=w.company_id AND x.environment=w.environment AND x.source_id=w.source_id AND x.claim_token=p_token AND x.state IN('leased','running','uncertain')) THEN
  DELETE FROM gridex_ediel_recovery.source_claims x WHERE x.company_id=w.company_id AND x.environment=w.environment AND x.source_id=w.source_id AND x.token=p_token;
 END IF;
 RETURN jsonb_build_object('state',w.state);
END $$;

-- The caller is an existing authenticated server operator action. Service-role
-- authentication plus the actor's existing tenant permission are both required.
-- This command cannot manufacture a terminal receipt or assert cancellation.
CREATE FUNCTION public.ediel_recovery_reconcile_v1(p_work uuid,p_token uuid,p_company uuid,p_expected_state text,p_actor uuid,p_reason text) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog SET lock_timeout TO '100ms' AS $$
DECLARE w gridex_ediel_recovery.work%rowtype;r gridex_ediel_recovery.terminal_receipts%rowtype;result jsonb;
BEGIN
 PERFORM gridex_ediel_recovery.service_v1();
 IF p_work IS NULL OR p_token IS NULL OR p_company IS NULL OR p_actor IS NULL OR p_expected_state IS DISTINCT FROM 'uncertain'
  OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 10 AND 1000 THEN RAISE EXCEPTION 'ediel_recovery_reconcile_input_invalid';END IF;
 IF public.gridex_actor_has_company_permission(p_actor,p_company,'communication.write') IS DISTINCT FROM true THEN RAISE EXCEPTION 'ediel_recovery_reconcile_actor_denied' USING ERRCODE='42501';END IF;
 SELECT * INTO w FROM gridex_ediel_recovery.work WHERE id=p_work AND company_id=p_company FOR UPDATE;
 IF NOT FOUND OR w.state<>p_expected_state OR w.claim_token IS DISTINCT FROM p_token THEN RAISE EXCEPTION 'ediel_recovery_reconcile_stale';END IF;
 SELECT * INTO r FROM gridex_ediel_recovery.terminal_receipts WHERE work_id=w.id AND company_id=w.company_id AND source_id=w.source_id AND token=p_token AND attempt=w.attempts;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','uncertain','heldBy','terminal_owner_receipt_missing');END IF;
 -- Re-qualify actual current source/outbox evidence as well as the immutable
 -- receipt. A deletion or changed scope cannot be replaced by an operator flag.
 PERFORM public.ediel_recovery_record_terminal_v1(w.id,p_token,w.company_id,w.state,r.outcome);
 result:=public.ediel_recovery_transition_v1(w.id,p_token,'finish');
 INSERT INTO gridex_ediel_recovery.reconcile_audit(company_id,work_id,token,actor_id,reason,receipt_id,from_state,to_state)
 VALUES(w.company_id,w.id,p_token,p_actor,btrim(p_reason),r.id,w.state,result->>'state');
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.ediel_recovery_record_terminal_v1(uuid,uuid,uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_recovery_record_terminal_v1(uuid,uuid,uuid,text,text) TO service_role;
REVOKE ALL ON FUNCTION public.ediel_recovery_reconcile_v1(uuid,uuid,uuid,text,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_recovery_reconcile_v1(uuid,uuid,uuid,text,uuid,text) TO service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA gridex_ediel_recovery FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.ediel_recovery_discover_v1(text,text,uuid,integer,integer,integer,integer) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.ediel_recovery_lease_v1(text,text,uuid,uuid[],integer,integer,integer) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.ediel_recovery_transition_v1(uuid,uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_recovery_discover_v1(text,text,uuid,integer,integer,integer,integer) TO service_role;
GRANT EXECUTE ON FUNCTION public.ediel_recovery_lease_v1(text,text,uuid,uuid[],integer,integer,integer) TO service_role;
GRANT EXECUTE ON FUNCTION public.ediel_recovery_transition_v1(uuid,uuid,text,text) TO service_role;
DO $owners$
DECLARE f record;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'ediel_recovery_migration_owner_required';END IF;
 FOR f IN SELECT p.oid::regprocedure identity FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='gridex_ediel_recovery' OR(n.nspname='public' AND p.proname IN('ediel_recovery_discover_v1','ediel_recovery_lease_v1','ediel_recovery_transition_v1','ediel_recovery_record_terminal_v1','ediel_recovery_reconcile_v1')) LOOP
  EXECUTE format('ALTER FUNCTION %s OWNER TO postgres',f.identity);
 END LOOP;
END $owners$;
COMMIT;
